  SR.saveTeam = function () { try { localStorage.setItem('sr_team', JSON.stringify(SR.TEAM)); } catch (e) {} };
  SR.addPerson = function (n) { n = (n || '').trim(); if (n && SR.TEAM.indexOf(n) < 0) { SR.TEAM.push(n); SR.saveTeam(); } };
  SR.removePerson = function (n) { SR.TEAM = SR.TEAM.filter(function (x) { return x !== n; }); SR.saveTeam(); };
