  /* ---- project math: promise -> clicks needed -> budget ---- */
  SR.projectMath = function (type, f) {
    var n = function (k) { var v = parseFloat(f[k]); return isNaN(v) ? 0 : v; };
    var cv = n('cvr') / 100;
    var clicksDay = cv ? n('leads') / 30 / cv : 0;
    var imprMonth = n('ctr') ? clicksDay * 30.4 / (n('ctr') / 100) : 0;
    var daily = type === 'gads' ? clicksDay * n('cpc') : imprMonth / 30.4 / 1000 * n('cpm');
    var monthly = daily * 30.4;
    var cpl = n('leads') ? monthly / n('leads') : 0;
    var deals = n('leads') * n('close') / 100;
    var rev = deals * n('deal');
    var roas = monthly && rev ? rev / monthly : 0;
    return { clicksDay: clicksDay, imprMonth: imprMonth, daily: daily, monthly: monthly, cpl: cpl, deals: deals, rev: rev, roas: roas };
  };

